                <span className="rounded-full bg-primary px-2 py-0.5 font-sans text-[12px] font-bold text-white">
                  {activeFilterCount}
                </span>
              ) : null}
            </SheetTitle>
          </SheetHeader>

          <div className="min-h-0 flex-1 space-y-6 overflow-y-auto px-5 py-4">
            <DestinationSidebar
              activeCategory={activeCategory}
