  return (
    <section className="relative h-[100px] overflow-hidden bg-secondary lg:h-[120px]">
      <Image
        src="/home assets/Heritage Banner.webp"
        alt="Ancient Trails heritage landscape"
        fill
        priority
        sizes="100vw"
        className="object-cover object-center"
      />
      <div className="absolute inset-0 bg-[linear-gradient(180deg,rgba(35,18,9,0.12)_0%,rgba(35,18,9,0.34)_100%)]" />
      <div className="home-wide-frame relative z-10 mx-auto w-full px-5 sm:px-0">
        <Header />
      </div>
    </section>
  );
}

function TourSidebar({
  activeFilterCount,
  durationFilter,
  isCollapsed,
  onClearFilters,
  onCollapsedChange,
  onDurationChange,
  onTypeToggle,
  selectedTypeValues,
  typeOptions,
}: {
  activeFilterCount: number;
  durationFilter: DurationFilter;
  isCollapsed: boolean;
  selectedTypeValues: string[];
  typeOptions: CountOption[];
  onClearFilters: () => void;
  onCollapsedChange: (value: boolean) => void;
  onDurationChange: (value: DurationFilter) => void;
  onTypeToggle: (value: string) => void;
}) {
  if (isCollapsed) {
    return (
      <aside className="hidden lg:sticky lg:top-5 lg:z-20 lg:block lg:self-start">
        <div className="flex items-center justify-center gap-2 rounded-[8px] border border-[#ead8c5] bg-white p-2 shadow-[0_12px_32px_rgba(67,43,27,0.07)] lg:flex-col">
          <button
            type="button"
            aria-label="Maximize tour filters"
            onClick={() => onCollapsedChange(false)}
            className="grid size-10 place-items-center rounded-[7px] border border-primary/25 bg-primary/8 text-primary transition-colors hover:border-primary hover:bg-primary hover:text-white"
          >
            <SlidersHorizontal className="size-4" strokeWidth={1.9} />
          </button>
          <CollapsedFilterButton
            active={selectedTypeValues.length > 0}
            icon={Sparkles}
            label="Open tour format filters"
            onClick={() => onCollapsedChange(false)}
          />
          <CollapsedFilterButton
            active={durationFilter !== "all"}
            icon={Clock3}
            label="Open duration filters"
            onClick={() => onCollapsedChange(false)}
          />
        </div>
      </aside>
    );
  }

  return (
    <aside className="hidden space-y-4 lg:sticky lg:top-5 lg:block lg:self-start">
      <div className="flex items-center justify-between gap-3 px-1">
        <h2 className="flex items-center gap-2 font-sans text-[14px] font-bold text-secondary/80">
          <SlidersHorizontal className="size-4 text-secondary/75" />
          Filters
        </h2>
        <div className="flex items-center gap-3">
         
          <button
            type="button"
            onClick={onClearFilters}
            disabled={activeFilterCount === 0}
            className="font-sans text-[11px] font-bold text-secondary/60 transition-colors hover:text-secondary disabled:pointer-events-none disabled:text-secondary/30"
          >
            Clear all
          </button>
        </div>
      </div>

      <div className="rounded-[8px] border border-[#ead8c5] bg-white p-4 shadow-[0_12px_32px_rgba(67,43,27,0.07)]">
        <div id="tour-filter-panel" className="space-y-6">
          <CheckboxGroup
            icon={Sparkles}
            options={typeOptions}
            selectedValues={selectedTypeValues}
            title="Tour Format"
            onToggle={onTypeToggle}
          />

          <RadioGroup
            icon={Clock3}
            options={durationOptions}
            title="Duration"
            value={durationFilter}
            onChange={(value) => onDurationChange(value as DurationFilter)}
          />

        </div>
      </div>
    </aside>
  );
}

function MobileTourActions({
  durationFilter,
  isFilterOpen,
  isQuoteOpen,
  onClearFilters,
  onDurationChange,
  onFilterOpenChange,
  onQuoteOpenChange,
  onTypeToggle,
  selectedTypeValues,
  typeOptions,
}: {
  durationFilter: DurationFilter;
  isFilterOpen: boolean;
  isQuoteOpen: boolean;
  selectedTypeValues: string[];
  typeOptions: CountOption[];
  onClearFilters: () => void;
  onDurationChange: (value: DurationFilter) => void;
  onFilterOpenChange: (open: boolean) => void;
  onQuoteOpenChange: (open: boolean) => void;
  onTypeToggle: (value: string) => void;
}) {
  const mobileFilterCount =
    selectedTypeValues.length + (durationFilter !== "all" ? 1 : 0);

  return (
    <>
      <div className="fixed inset-x-0 bottom-0 z-40 border-t border-[#ead8c5] bg-white/96 px-2 pb-[max(0.45rem,env(safe-area-inset-bottom))] pt-1.5 shadow-[0_-12px_30px_rgba(18,32,44,0.13)] backdrop-blur lg:hidden">
