      onClick={onClick}
    >
      <span className="grid size-8 shrink-0 place-items-center rounded-full bg-primary text-white">
        <Icon className="size-3.5" strokeWidth={2.2} />
      </span>
      <span className="truncate">{label}</span>
      
    </button>
