function CheckboxGroup({
  icon: Icon,
  onToggle,
  options,
  selectedValues,
  title,
}: {
  icon: LucideIcon;
  options: CountOption[];
  selectedValues: string[];
  title: string;
  onToggle: (value: string) => void;
}) {
