function getTravellerInitials(user: TravellerUser | null) {
  if (!user) {
    return "TR";
  }

  const parts = [user.firstName, user.lastName]
    .map((part) => part?.trim())
    .filter(Boolean);

  if (parts.length >= 2) {
    return `${parts[0][0]}${parts[1][0]}`;
  }

  return (parts[0] || user.email || "TR").slice(0, 2);
}

function getGuestName(guest?: {
  firstName?: string;
